import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"IDE 设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/settings/ide-setting.md","filePath":"zh/settings/ide-setting.md","lastUpdated":1785990345000}'),o={name:"zh/settings/ide-setting.md"};function n(s,t,i,h,c,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="ide-设置" tabindex="-1">IDE 设置 <a class="header-anchor" href="#ide-设置" aria-label="Permalink to &quot;IDE 设置&quot;">​</a></h1><p>EasyYapi 提供了 IDE 级别的设置，可以在 IDEA 中进行配置。</p><h2 id="打开设置" tabindex="-1">打开设置 <a class="header-anchor" href="#打开设置" aria-label="Permalink to &quot;打开设置&quot;">​</a></h2><p><kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd></p><h2 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td>postman.url</td><td>Postman 导出 URL</td></tr><tr><td>postman.token</td><td>Postman API Token</td></tr><tr><td>yapi.server</td><td>YApi 服务器地址</td></tr><tr><td>yapi.token</td><td>YApi 项目 Token</td></tr><tr><td>project.name</td><td>项目名称</td></tr></tbody></table><h2 id="导出设置" tabindex="-1">导出设置 <a class="header-anchor" href="#导出设置" aria-label="Permalink to &quot;导出设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td>outputDemo</td><td>导出 Markdown 时生成响应 demo</td></tr><tr><td>outputCharset</td><td>导出字符集</td></tr></tbody></table><h2 id="框架开关" tabindex="-1">框架开关 <a class="header-anchor" href="#框架开关" aria-label="Permalink to &quot;框架开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td>feignEnable</td><td>启用 Feign 客户端支持</td><td><code>false</code></td></tr><tr><td>jaxrsEnable</td><td>启用 JAX-RS 支持</td><td><code>true</code></td></tr><tr><td>actuatorEnable</td><td>启用 Spring Actuator 支持</td><td><code>false</code></td></tr><tr><td>grpcEnable</td><td>启用 gRPC 支持</td><td><code>true</code></td></tr><tr><td>swaggerEnable</td><td>启用 Swagger 支持</td><td><code>true</code></td></tr><tr><td>swagger3Enable</td><td>启用 Swagger 3 / OpenAPI 支持</td><td><code>true</code></td></tr></tbody></table><h2 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h2><p>EasyYapi 内置了推荐配置，可以在设置中启用。推荐配置包含常用的规则和类型转换。</p><h2 id="features-标签页" tabindex="-1">Features 标签页 <a class="header-anchor" href="#features-标签页" aria-label="Permalink to &quot;Features 标签页&quot;">​</a></h2><p>EasyYapi 3.2 使用 <strong>Features</strong> 标签页统一管理扩展点的启用状态。列表会根据已安装的插件组件动态生成：</p><table tabindex="0"><thead><tr><th>分区</th><th>控制内容</th></tr></thead><tbody><tr><td><strong>Framework Support</strong></td><td>Feign、JAX-RS、Actuator、gRPC 和 Custom 等框架识别器。</td></tr><tr><td><strong>Export Channels</strong></td><td>YApi、Postman、Markdown、cURL、HttpClient、Hoppscotch (Beta) 和 OpenAPI (Beta) 等导出渠道。实验性渠道默认关闭。</td></tr><tr><td><strong>Field Format Channels</strong></td><td>JSON、JSON5、Properties、YAML 等字段格式化渠道。</td></tr></tbody></table><p>大部分框架识别器、导出渠道、字段格式化渠道和扩展配置都可以在 Settings 中启用或关闭。General 标签页还提供 API 扫描、自动/并发扫描和编辑器行标记等开关。</p><p>General 标签页中的 <strong>Enable API scanning</strong> 是 API 发现的总开关。关闭后，自动扫描、并发扫描和 API 行标记都会被关闭。</p><h2 id="curl" tabindex="-1">cURL <a class="header-anchor" href="#curl" aria-label="Permalink to &quot;cURL&quot;">​</a></h2><p>cURL 设置页控制变量渲染，以及批量导出和 Dashboard <strong>Copy as cURL</strong> 使用的默认值：</p><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>Render mode</strong></td><td>保留占位符、使用当前环境解析，或每次导出询问。环境值优先于配置读取器的值。</td></tr><tr><td><strong>Copy from edited</strong></td><td>复制 cURL 时使用 Dashboard 中编辑后的接口，而不是源代码接口。</td></tr><tr><td><strong>Include comments and section dividers</strong></td><td>在批量脚本中添加接口标题和分隔线。</td></tr><tr><td><strong>Pretty-print JSON body</strong></td><td>为 JSON 请求体添加缩进。</td></tr><tr><td><strong>Multi-line format</strong></td><td>每行输出一个 cURL 参数。</td></tr><tr><td><strong>Long flags</strong></td><td>使用 <code>--request</code>、<code>--header</code>、<code>--data</code>、<code>--form</code> 等长参数名。</td></tr><tr><td><strong>Response example</strong></td><td>将可用的响应体示例追加为注释。</td></tr><tr><td><strong>Run pre-request scripts</strong></td><td>批量导出执行文件夹/类脚本，单接口复制还会执行接口级脚本。</td></tr></tbody></table><p>导出对话框可以针对单次导出覆盖格式化和请求前脚本选项。</p><h2 id="openapi-beta" tabindex="-1">OpenAPI (Beta) <a class="header-anchor" href="#openapi-beta" aria-label="Permalink to &quot;OpenAPI (Beta)&quot;">​</a></h2><p>OpenAPI 导出默认关闭。通过 <strong>Features</strong> 启用后，OpenAPI 设置页可以选择 <strong>JSON</strong>、<strong>YAML</strong> 或 <strong>Ask each export</strong>。默认文件名为 <code>openapi.json</code> 和 <code>openapi.yaml</code>。</p><p>文档级元数据通过 <code>openapi.info.title</code>、<code>openapi.info.version</code>、<code>openapi.info.description</code> 和 <code>openapi.server.url</code> 规则配置，也兼容旧的 <code>openapi.host</code>。详见<a href="/zh/guide/export-openapi">导出到 OpenAPI</a>。</p><h2 id="custom-框架" tabindex="-1">Custom 框架 <a class="header-anchor" href="#custom-框架" aria-label="Permalink to &quot;Custom 框架&quot;">​</a></h2><p>Custom 框架默认关闭，可以在 <strong>Features</strong> &gt; <strong>Framework Support</strong> 中启用。它提供可选的行标记开关；实际接口提取由 <code>custom.*</code> 规则控制。详见 <a href="/zh/framework/custom">Custom 框架</a>。</p>',26)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
